// Sets default values
ACookingMachine::ACookingMachine()
{
 	// Set this actor to call Tick() every frame.  You can turn this off to improve performance if you don't need it.
	PrimaryActorTick.bCanEverTick = true;
	ItemMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("CookingMeshComponent"));
	ItemMesh->SetupAttachment(GetRootComponent());
	RootComponent = ItemMesh;
	
	BoxCollision = CreateDefaultSubobject<UBoxComponent>(TEXT("Box Collision"));
	BoxCollision->SetupAttachment(GetRootComponent());
	BoxCollision->SetGenerateOverlapEvents(true);
	BoxCollision->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
	BoxCollision->SetCollisionResponseToAllChannels(ECollisionResponse::ECR_Overlap);
	//BoxCollision->SetCollisionResponseToChannel(ECollisionChannel::ECC_Pawn, ECollisionResponse::ECR_Ignore);
	// 视口里未选中也画出判定盒（青色=台面设备），方便摆放时目测交互范围
	BoxCollision->ShapeColor = FColor(40, 190, 200);
	BoxCollision->bDrawOnlyIfSelected = false;

	TipsWidget = CreateDefaultSubobject<UWidgetComponent>(TEXT("TipsWidget"));
	TipsWidget->SetupAttachment(GetRootComponent());
	TipsWidget->SetVisibility(false);

	// 烹饪进度卡片：世界空间、朝相机；纯 C++ 控件，不依赖蓝图资产
	ProgressWidgetComp = CreateDefaultSubobject<UWidgetComponent>(TEXT("ProgressWidget"));
	ProgressWidgetComp->SetupAttachment(GetRootComponent());
	ProgressWidgetComp->SetWidgetSpace(EWidgetSpace::World);
	ProgressWidgetComp->SetDrawSize(FVector2D(220.f, 48.f));
	ProgressWidgetComp->SetRelativeLocation(FVector(0.f, 0.f, 160.f));
	ProgressWidgetComp->SetTwoSided(true);
	ProgressWidgetComp->SetVisibility(false);

	// —— 生成位置标记 ——
	SpawnPoint = CreateDefaultSubobject<USceneComponent>(TEXT("SpawnPoint"));
	SpawnPoint->SetupAttachment(GetRootComponent());
}


void ACookingMachine::OnConstruction(const FTransform& Transform)
{
	Super::OnConstruction(Transform);

	// 编辑器视口预览：改 InteractionBoxExtent 立刻反映到盒体上
	ApplyInteractionScale();
}

void ACookingMachine::ApplyInteractionScale()
{
	// ============ 统一交互判定尺度 ============
	// 强制按统一标准重设：引擎默认盒体只有 32 立方（贴在 pivot 高度），
	// 玩家站在长条灶台的端头就会“够不到”，这是灶台交互范围最典型的错位来源。
	if (BoxCollision)
	{
		BoxCollision->SetBoxExtent(InteractionBoxExtent * InteractionScale::Get(), false);
		BoxCollision->SetRelativeLocation(FVector(0.f, 0.f, InteractionCenterHeight));
		BoxCollision->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
		BoxCollision->SetCollisionResponseToAllChannels(ECR_Overlap);
		BoxCollision->SetGenerateOverlapEvents(true);
	}
}

// Called when the game starts or when spawned
void ACookingMachine::BeginPlay()
{
	ResetFoodData();
	Tags.Add("Machine");
	Super::BeginPlay();

	ApplyInteractionScale();
	RefreshShopLock();

	BoxCollision->OnComponentBeginOverlap.AddDynamic(this, &ACookingMachine::OnBoxOverlap);
	BoxCollision->OnComponentEndOverlap.AddDynamic(this, &ACookingMachine::OnBoxEndOverlap);

	// 运行时创建进度卡片控件：编辑器里不需要预先配 WBP
	if (ProgressWidgetComp)
	{
		ProgressWidget = CreateWidget<UResearchProgressWidget>(GetWorld(), UResearchProgressWidget::StaticClass());
		if (ProgressWidget)
		{
			ProgressWidgetComp->SetWidget(ProgressWidget);
		}
		else
		{
			ProgressWidgetComp->SetVisibility(false);
		}
	}
}

void ACookingMachine::ResetFoodData()
{
	TargetMenuData.FoodID = -2;
	TargetMateiralCount = 0;
	CurFoodCount = 0;
	CurCookingTime = 0;
	CurRepairTime = 0;
	Repairing = false;
	IsFull = false;
	OnFire = false;
	IsCooking = false;
	IsFinish = false;
	OverCookTime = 0;
	PotentialMenuIDs.Empty(4);
	FoodMaterial.Empty(6);
	// 新的一锅：复位"没碟子"提示，允许再次提示
	bNoPlateNotified = false;
	bWaitingForPlate = false;
	bAttentionPerformed = false;
	// 状态复位后卡片立即隐藏，不等下一帧 Tick
	if (ProgressWidgetComp)
	{
		ProgressWidgetComp->SetVisibility(false);
	}
}

void ACookingMachine::UpdateProgressWidget()
{
	if (!ProgressWidgetComp)
	{
		return;
	}

	const float RequiredTime = GetRequiredCookTime();
	// 熟了之后（IsFinish，可能还在保温/超时）由取餐提示接管，进度卡片不再显示
	const bool bShow = IsCooking && !IsFinish && !OnFire && RequiredTime > KINDA_SMALL_NUMBER;
	ProgressWidgetComp->SetVisibility(bShow);
	if (!bShow || !ProgressWidget)
	{
		return;
	}

	const float ElapsedTime = CurCookingTime + OverCookTime;
	const FString Verb = IsAttentionAvailable() ? TEXT("按 E 翻面 · 可获佳品")
		: bAttentionPerformed ? TEXT("✓ 已翻面") : TEXT("烹饪中");
	ProgressWidget->SetProgress(FMath::Max(0.f, RequiredTime - ElapsedTime), RequiredTime, Verb, bAttentionPerformed);
	ProgressWidget->SetIngredientCounts(FoodMaterial);
	// 带食材图标行时卡片会变高，世界空间控件不会自动跟着长
	ProgressWidgetComp->SetDrawSize(ProgressWidget->GetCardDrawSize());

	// 游戏相机接近俯视，世界空间控件保持竖直时几乎只剩一条黑边；
	// 每帧转向相机才能看清进度与食材图标
	const APlayerController* PC = GetWorld() ? GetWorld()->GetFirstPlayerController() : nullptr;
	if (PC && PC->PlayerCameraManager)
	{
		const FVector ToCamera = PC->PlayerCameraManager->GetCameraLocation() - ProgressWidgetComp->GetComponentLocation();
		ProgressWidgetComp->SetWorldRotation(ToCamera.Rotation());
	}
}

APlateSystem* ACookingMachine::FindPlateSystem() const
{
	// 优先关卡蓝图上的实例
	if (const UWorld* W = GetWorld())
	{
		if (UBaseGameInstance* GI = Cast<UBaseGameInstance>(W->GetGameInstance()))
		{
			if (GI->curLevelBP && GI->curLevelBP->PlateSystem)
			{
				return GI->curLevelBP->PlateSystem;
			}
		}
	}

	// 回退：场景中第一个盘子系统
	if (UWorld* W = GetWorld())
	{
		return Cast<APlateSystem>(UGameplayStatics::GetActorOfClass(W, APlateSystem::StaticClass()));
	}
	return nullptr;
}
void ACookingMachine::CollectCandidateMenus(TArray<FMenuData>& OutMenus) const
{
	OutMenus.Reset();

	UBaseGameInstance* GI = nullptr;
	if (const UWorld* W = GetWorld())
	{
		GI = Cast<UBaseGameInstance>(W->GetGameInstance());
	}

	// 首选：按 MachineID 从菜品表取本机可做的菜（菜品的 MachineID=0 视为通用，见 GetFoodIDsByMachine）
	if (MachineID > 0 && GI && GI->foodSystem)
	{
		for (int32 FoodID : GI->foodSystem->GetFoodIDsByMachine(MachineID))
		{
			// 研究炉没解锁的菜谱不下锅：否则“研究解锁”只影响订单，玩家照样能直接做
			if (!GI->IsRecipeUnlocked(FoodID))
			{
				continue;
			}
			FMenuData Data = GI->foodSystem->GetMenuData(FoodID);
			if (Data.FoodID >= 0)
			{
				OutMenus.Add(MoveTemp(Data));
			}
		}
	}

	if (OutMenus.Num() > 0)
	{
		return;
	}

	// 兜底：MachineID 未配置（0）或菜品表还没初始化时，沿用蓝图上手填的 MenuIDsArray（兼容旧配置）
	for (const FDataTableRowHandle& Handle : MenuIDsArray)
	{
		const FMenuData* Row = Handle.GetRow<FMenuData>(TEXT("CookingMachine::CollectCandidateMenus"));
		if (!Row)
		{
			const FString DTName = Handle.DataTable ? Handle.DataTable->GetName() : TEXT("NULL");
			GEngine->AddOnScreenDebugMessage(-1, 5.f, FColor::Red,
				FString::Printf(TEXT("[CheckMenu] 菜品行无效 -> DataTable:%s, RowName:%s (DataTable为空或RowName不存在)"),
					*DTName, *Handle.RowName.ToString()));
			continue;
		}

		FMenuData Data = *Row;
		// 行名约定为 FoodID：以行名为准，行名不是数字时退回行内字段
		Data.FoodID = Row->ResolveFoodID(Handle.RowName);
		if (GI && !GI->IsRecipeUnlocked(Data.FoodID))
		{
			continue;
		}
		OutMenus.Add(MoveTemp(Data));
	}
}

bool ACookingMachine::FindMatchMenu(int32 FoodMaterialID,FMenuData& matchMenuData)
{
	TArray<FMenuData> CandidateMenus;
	CollectCandidateMenus(CandidateMenus);

	float minCookingTime = MAX_FLT;
	int minCookingMateiralCount = 10000;
	bool canFind = false;
	for (const FMenuData& menuData : CandidateMenus)
	{
		//最少食材
		if (menuData.FoodID != -1 && menuData.MenuItems.Contains(FoodMaterialID) && menuData.MenuItems.Num() <= minCookingMateiralCount  )
		{
			//最短时间
			if (menuData.CookingTime < minCookingTime)
			{
				matchMenuData = menuData;
				if (!canFind)
					canFind = true;
			}
		}
	}
	return canFind;
}

bool ACookingMachine::CheckMenu(int32 FoodMaterialID,FMenuData& matchMenuData)
{
	bool canFind = false;
	auto curFoodMaterialID = FoodMaterial;
	if (!curFoodMaterialID.Contains(FoodMaterialID))
		curFoodMaterialID.Add(FoodMaterialID,1);
	else
		curFoodMaterialID[FoodMaterialID] += 1;
	float minCookingTime = MAX_FLT;
	int minCookingMateiralCount = 10000;

	TArray<FMenuData> CandidateMenus;
	CollectCandidateMenus(CandidateMenus);

	for (const FMenuData& menuData : CandidateMenus) //遍历可制作菜单
	{
		if (menuData.FoodID >=0 && menuData.MenuItems.Num() >= curFoodMaterialID.Num() )
		{
			bool match = true;
			//找包含当前食材都包括的菜单
			for (const TPair<int, int>& foodMat : curFoodMaterialID) //遍历当前容器食材
			{
				int foodMatID = foodMat.Key;
				int foodMatNum = foodMat.Value;
				if (!menuData.MenuItems.Contains(foodMatID) || menuData.MenuItems[foodMatID] < foodMatNum) 
				{
					match = false;
					break;
				}
			}
			if (match)
			{
				//记录食材最少和最短时间的作为当前菜单
				int numOfItems = menuData.GetNumOfItems();
				if (numOfItems < minCookingMateiralCount)
				{
					//if (menuData.CookingTime < minCookingTime)
					{
						minCookingMateiralCount = numOfItems;
						minCookingTime = menuData.CookingTime;
						matchMenuData = menuData;
						if (!canFind)
							canFind = true;
					}
				}
			}
		}
	}
	return canFind;
}
