ADishwasher::ADishwasher()
{
	PrimaryActorTick.bCanEverTick = false;

	// 外观模型作为根组件，交互球挂在其上
	DishwasherMesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("DishwasherMesh"));
	RootComponent = DishwasherMesh;

	InteractionSphere = CreateDefaultSubobject<USphereComponent>(TEXT("InteractionSphere"));
	InteractionSphere->SetupAttachment(RootComponent);
	InteractionSphere->SetSphereRadius(InteractionRadius * InteractionScale::Get());
	// 视口里未选中也画出判定球，摆放关卡时能直接目测交互范围
	InteractionSphere->ShapeColor = FColor(40, 190, 200);
	InteractionSphere->bDrawOnlyIfSelected = false;
	InteractionSphere->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
	InteractionSphere->SetCollisionResponseToAllChannels(ECR_Overlap);
	InteractionSphere->SetGenerateOverlapEvents(true);

	// 交互提示控件（如"按 E 洗碟子"）：默认隐藏，靠近时显示；Widget Class 由蓝图在组件上配置
	TipsWidget = CreateDefaultSubobject<UWidgetComponent>(TEXT("TipsWidget"));
	TipsWidget->SetupAttachment(RootComponent);
	TipsWidget->SetVisibility(false);
}

void ADishwasher::OnConstruction(const FTransform& Transform)
{
	Super::OnConstruction(Transform);

	// 编辑器视口预览：改 InteractionRadius 立刻反映到组件上，
	// 摆放关卡时看到的球就是运行时真正生效的判定范围
	ApplyInteractionScale();
}

void ADishwasher::ApplyInteractionScale()
{
	if (InteractionSphere)
	{
		InteractionSphere->SetSphereRadius(InteractionRadius * InteractionScale::Get(), false);
		InteractionSphere->SetRelativeLocation(FVector(0.f, 0.f, InteractionCenterHeight));
		InteractionSphere->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
		InteractionSphere->SetCollisionResponseToAllChannels(ECR_Overlap);
		InteractionSphere->SetGenerateOverlapEvents(true);
	}
}

void ADishwasher::BeginPlay()
{
	Super::BeginPlay();

	// 统一交互尺度：强制覆盖蓝图里残留的旧半径
	ApplyInteractionScale();

	InteractionSphere->OnComponentBeginOverlap.AddDynamic(this, &ADishwasher::OnInteractionOverlap);
	InteractionSphere->OnComponentEndOverlap.AddDynamic(this, &ADishwasher::OnInteractionEndOverlap);

	// 在本洗碗机上直接配置本关碟子总数（>0 时覆盖盘子系统已有配置）。
	// 第二个参数 bFillAvailable=true：开局所有碟子都是干净的，把"可用碟子数"补满到总数，
	// 否则可用数还停留在系统默认值，烹饪机会误判"没有空闲碟子"而不出成品。
	if (TotalPlates > 0)
	{
		if (APlateSystem* PS = FindPlateSystem())
		{
			PS->SetTotalCount(TotalPlates, true);
			UE_LOG(LogTemp, Log, TEXT("[Dishwasher] 配置本关碟子总数 = %d（当前可用 %d）"), TotalPlates, PS->CurOrderIndex);
		}
		else
		{
			UE_LOG(LogTemp, Warning, TEXT("[Dishwasher] TotalPlates=%d 已配置，但 BeginPlay 时还没拿到盘子系统，稍后由 ABaseLevelBP 补上"), TotalPlates);
		}
	}
}

APlateSystem* ADishwasher::FindPlateSystem() const
{
	// 优先关卡蓝图上的实例
	if (const UWorld* W = GetWorld())
	{
		if (UBaseGameInstance* GI = Cast<UBaseGameInstance>(W->GetGameInstance()))
		{
			if (GI->curLevelBP && GI->curLevelBP->PlateSystem)
			{
				return GI->curLevelBP->PlateSystem;
			}
		}
	}

	// 回退：场景中第一个盘子系统
	if (UWorld* W = GetWorld())
	{
		return Cast<APlateSystem>(UGameplayStatics::GetActorOfClass(W, APlateSystem::StaticClass()));
	}
	return nullptr;
}

bool ADishwasher::UnlockCollectionTray()
{
	if (IsValid(CollectionTray))
	{
		return false;
	}
	FActorSpawnParameters Params;
	Params.Owner = this;
	Params.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
	CollectionTray = GetWorld()->SpawnActor<APlateCollectionTray>(
		APlateCollectionTray::StaticClass(), GetActorLocation(), GetActorRotation(), Params);
	if (!CollectionTray)
	{
		return false;
	}
	DockCollectionTray();
	return true;
}

void ADishwasher::DockCollectionTray()
{
	CollectionTray->DeAttachMeshToSocket();
	CollectionTray->AttachMeshToSocket(DishwasherMesh, NAME_None);
	const FBox Bounds = DishwasherMesh->Bounds.GetBox();
	FVector Rest = Bounds.GetCenter() + GetActorForwardVector() * 19.f;
	Rest.Z = Bounds.Max.Z;
	CollectionTray->SetActorLocation(Rest);
	CollectionTray->SetItemState(EItemState::EIS_Idle);
}

bool ADishwasher::HasDockedTray() const
{
	return IsValid(CollectionTray) && CollectionTray->GetAttachParentActor() == this;
}

bool ADishwasher::TakeCollectionTray(AShootCharacter& Player)
{
	if (!HasDockedTray() || Player.GetPickingItem())
	{
		return false;
	}
	Player.HoldItemInHand(CollectionTray);
	return true;
}

bool ADishwasher::ReturnCollectionTray(AShootCharacter& Player)
{
	if (!IsValid(CollectionTray) || Player.GetPickingItem() != CollectionTray || CollectionTray->GetPlateCount() > 0)
	{
		return false;
	}
	DockCollectionTray();
	Player.ClearHeldItemState();
	return true;
}

bool ADishwasher::SubmitPlate(AItemActor* Plate)
{
	if (!IsValid(Plate) || Plate->IsActorBeingDestroyed())
	{
		OnPlateReturnFailed(TEXT("NoPlate"));
		return false;
	}

	// 只接受脏碟（玩家从桌上收走的），避免把做好的菜/食材误交还
	if (bRequireDirtyPlate && !Plate->bIsDirtyPlate)
	{
		UE_LOG(LogTemp, Log, TEXT("[Dishwasher] 交还失败：手持物(%s)不是待清洗的脏碟"), *Plate->GetName());
		OnPlateReturnFailed(TEXT("NotDirty"));
		return false;
	}

	APlateSystem* PS = FindPlateSystem();
	if (!PS)
	{
		UE_LOG(LogTemp, Warning, TEXT("[Dishwasher] 交还失败：找不到盘子系统(APlateSystem)"));
		if (GEngine)
		{
			GEngine->AddOnScreenDebugMessage(-1, 3.f, FColor::Red, TEXT("[洗碗机] 找不到盘子系统(PlateSystem)"));
		}
		OnPlateReturnFailed(TEXT("NoPlateSystem"));
		return false;
	}

	// 可用碟子数 +1（上限为碟子总数 TotalCount）
	if (!Plate->ReturnServingPlate())
	{
		PS->AddPlate();
	}
	const int32 Available = PS->CurOrderIndex;

	// 碟子消失
	Plate->Destroy();

	UE_LOG(LogTemp, Log, TEXT("[Dishwasher] 碟子已交还清洗：可用碟子 %d/%d"), Available, PS->TotalCount);
	if (GEngine)
	{
		GEngine->AddOnScreenDebugMessage(-1, 3.f, FColor::Green,
			FString::Printf(TEXT("[洗碗机] 碟子已清洗，可用碟子 %d/%d"), Available, PS->TotalCount));
	}

	OnPlateReturned(Available);
	return true;
}

int32 ADishwasher::GetAvailablePlates() const
{
	if (const APlateSystem* PS = FindPlateSystem())
	{
		return PS->GetAvailablePlates();
	}
	return 0;
}

int32 ADishwasher::GetTotalPlates() const
{
	if (const APlateSystem* PS = FindPlateSystem())
	{
		return PS->TotalCount;
	}
	return 0;
}

void ADishwasher::OnInteractionOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult& SweepResult)
{
	AShootCharacter* Character = Cast<AShootCharacter>(OtherActor);
	if (!Character)
	{
		return;
	}

	Character->AddOverlappingDishwasher(this);

	// 当提示控件未被其它玩家占用时，显示"按 E 洗碟子"提示。
	// 默认关闭：E 提示统一由角色显示（每个本地玩家一份），TipsWidget 只做位置锚点。
	if (LocalPlayer == nullptr && TipsWidget && InteractionPromptTuning::UseDeviceOwnPromptTips())
	{
		TipsWidget->SetVisibility(true);
		if (APawn* AP = Cast<APawn>(OtherActor))
		{
			if (APlayerController* APC = Cast<APlayerController>(AP->GetController()))
			{
				if (ULocalPlayer* LP = APC->GetLocalPlayer())
				{
					// 设置 OwnerPlayer，使控件归属于该本地玩家（多人分屏隔离）
					TipsWidget->SetOwnerPlayer(LP);
					LocalPlayer = LP;
				}
			}
		}
	}
}

void ADishwasher::OnInteractionEndOverlap(UPrimitiveComponent* OverlappedComponent, AActor* OtherActor,
	UPrimitiveComponent* OtherComp, int32 OtherBodyIndex)
{
	AShootCharacter* Character = Cast<AShootCharacter>(OtherActor);
	if (!Character)
	{
		return;
	}

	// 只注销自己：多台洗碗机范围交叠时，另一台仍是候选目标
	Character->RemoveOverlappingDishwasher(this);

	// 离开时隐藏提示控件（仅当占用者正是该玩家）
	if (LocalPlayer && TipsWidget)
	{
		if (APawn* AP = Cast<APawn>(OtherActor))
		{
			if (APlayerController* APC = Cast<APlayerController>(AP->GetController()))
			{
				if (ULocalPlayer* LP = APC->GetLocalPlayer())
				{
					if (LocalPlayer == LP)
					{
						TipsWidget->SetVisibility(false);
						LocalPlayer = nullptr;
					}
				}
			}
		}
	}
}

