void UHUDWidget::BindEconomy(UEconomySystem* Eco)
{
	Economy = Eco;
	if (Eco)
	{
		Eco->OnReputationChanged.AddDynamic(this, &UHUDWidget::HandleReputationChanged);
		Eco->OnMoneyChanged.AddDynamic(this, &UHUDWidget::HandleMoneyChanged);
		RefreshGoal();
	}
