	UTextBlock* Text(UWidgetTree* Tree, FName Name, const FText& Value, int32 FontSize, const TCHAR* Ink)
	{
		UTextBlock* Block = Tree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), Name);
