		int32 MaxLevel;
		EShopOfferKind Kind;
		int32 TrayTier; // 0=4 盘, 1=6 盘, 2=8 盘
	};

	const FShopOffer GShopOffers[] = {
		{EconomyShopItemIDs::TraySmall, TEXT("托盘 · 小"), TEXT("一次可收纳 4 个空碟，适合刚起步的小店。"), 80, 1, EShopOfferKind::Tray, 0},
