#pragma once

#include "CoreMinimal.h"
#include "UObject/NoExportTypes.h"
#include "Game/EconomySystem.h"
#include "Game/BusinessTime.h"
#include "Game/StaffSystem.h"
#include "BusinessSimulation.generated.h"

class USeasonSystem;

/** 一份经营报表（日 / 月 / 年 结算时广播给 UI） */
USTRUCT(BlueprintType)
struct FBusinessReport
{
	GENERATED_BODY()

	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Year = 1;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Month = 1;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Day = 1;

	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Income = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Expense = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Net = 0;

	/** 营业利润不含设备投资；现金流仍由 Net 展示。 */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 OperatingNet = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Investment = 0;

	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Money = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Reputation = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 Stars = 0;
};

DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnBusinessReport, const FBusinessReport&, Report);
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnStarsChanged, int32, NewStars);

/**
 * 开罗式经营模拟核心（取代"关卡制"）：
 *  - 持有 时钟(UTimeSystem) + 员工(UStaffSystem) + 经济(UEconomySystem)；
 *  - 日 / 月 / 年 结算：收入(顾客消费、租金、赛事奖金) 与 支出(工资、维护、投资)；
 *  - 由声誉 + 设施 + 服务品质 计算"经营星级"(RestaurantStars)，
 *    取代原 FLevelInfo（已合并进 FLevelGoalRow）里用于关卡过关的 star 字段。
 *
 * 营收→扩建 / 研发 / 招人 的"投入"走现有 EconomySystem(BuyItem / SpendMoney)；
 * 招人→培养属性→(出餐更快 / 服务更好 / 维护更低 / 招客更多) 形成资源循环。
 */
UCLASS(Blueprintable)
class SHOOT_API UBusinessSimulation : public UObject
{
	GENERATED_BODY()

public:
	/**
	 * 时钟类：默认 UTimeSystem。可在继承 UBusinessSimulation 的蓝图（或本类实例的 Class Defaults）里
	 * 替换为 UTimeSystem 的蓝图子类，从而在不改 C++ 的情况下调参（一天时长、营业时段、太阳颜色/强度等）。
	 * 留空则回退到 UTimeSystem。
	 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Business|Time")
	TSubclassOf<UTimeSystem> TimeSystemClass;

	/** 时钟（Init 时按 TimeSystemClass 自动创建） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	TObjectPtr<UTimeSystem> TimeSystem;

	/** 员工系统（Init 时自动创建） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	TObjectPtr<UStaffSystem> StaffSystem;

	/** 经济系统（由 GameInstance 注入） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	TObjectPtr<UEconomySystem> Economy;

	/** 赛季系统（由 GameInstance 注入）：星级阈值与日评级都走它 */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	TObjectPtr<USeasonSystem> SeasonSystem;

	/** 员工工资是否按日计提（月薪 / 30）；开启后月末不再重复发薪 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Business")
	bool bAccrueWagesDaily = true;

	// ---- 经营参数（也可后续迁移到数据表） ----
	/** 每日租金 / 设施被动收入 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Business", meta = (ClampMin = "0"))
	int32 DailyRentIncome = 50;
	/** 每日设施维护支出（受管理加成减免） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Business", meta = (ClampMin = "0"))
	int32 DailyMaintenance = 20;
	/** 每年赛事奖金池上限（年末随机抽取 0~该值 作为奖金） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Business", meta = (ClampMin = "0"))
	int32 YearlyPrizePool = 2000;

	// ---- 账本（滚动累计，结算时重置对应周期） ----
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 TodayIncome = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 TodayExpense = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 TodayInvestment = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 MonthIncome = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 MonthExpense = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 YearIncome = 0;
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business") int32 YearExpense = 0;

	/** 经营星级（0~5），取代关卡 star */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Business")
	int32 RestaurantStars = 0;

	// ---- 事件 ----
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Business")
	FOnBusinessReport OnDailyReport;
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Business")
	FOnBusinessReport OnMonthlyReport;
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Business")
	FOnBusinessReport OnYearlyReport;
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Business")
	FOnStarsChanged OnStarsChanged;

	/** 初始化：创建时钟/员工、绑定日期事件与经济变化监听 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Business")
	void Init(UEconomySystem* InEconomy);

	/** 退役实例：停掉时钟 Tick 并解除所有委托（被新实例替换时调用，避免双时钟并行推进） */
	void Shutdown();

	/** 当前星级 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Business")
	int32 GetStars() const { return RestaurantStars; }

	/** 重算经营星级（赛季系统注入后 / 读档后由外部调用） */
