	virtual void Tick(float DeltaTime) override;
	/** huanglily：CDO / 原型对象不能参与 Tick，否则编辑器里类默认值的 DayProgress 会自行漂移 */
	virtual bool IsTickable() const override { return !HasAnyFlags(RF_ClassDefaultObject | RF_ArchetypeObject); }
	virtual TStatId GetStatId() const override
	{
		RETURN_QUICK_DECLARE_CYCLE_STAT(UTimeSystem, STATGROUP_Tickables);
	}

private:
	void AdvanceOneDay(bool bResetDayProgress = false);
	void UpdateBusinessState();
	bool HasPendingClosingGuests() const;
	/** 进入当日营业结束时把经营时钟拨到打烊时刻（如 22:00），让场景与 HUD 同步显示“已打烊”。 */
	void SnapClockToClosingHour();

	double Accum = 0.0;
	bool bPausedState = false;
	bool bBusinessClosedForDay = false;
	/** 当日营业已到打烊点：暂停时钟，直到玩家点“进入下一天” */
	bool bEndOfDayReached = false;
	/** 打烊后强制夜晚视觉（覆盖常亮白天） */
	bool bNightVisualsForced = false;
};

