	UFUNCTION(BlueprintCallable, Category = "Shoot|Season")
	void NotifyOrderServed(float WaitSeconds, bool bWildOrder, int32 OrderPrice);

	/** 订单超时失败上报 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Season")
	void NotifyOrderFailed();

