		FTutorialTaskRow Row;
		int32 Progress = 0;
		int32 MaxSeen = 0;
		/** 带篮子采摘：上一帧全场篮子里的目标食材总数，用于只累计“增加”的部分 */
		int32 LastBasketTotal = 0;
		bool bDone = false;
	};

