	FText FocusHint;
	FVector FocusLocation = FVector::ZeroVector;
	bool bHasFocusTarget = false;
	bool bRestoring = false;
	bool bSavePending = false;
	UPROPERTY()
	TSubclassOf<AItemActor> PracticePlateClass;

