// Fill out your copyright notice in the Description page of Project Settings.

#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "Engine/DataTable.h"
#include "Interfaces/HoveringInterface.h"
#include "Data/QualityTypes.h"
#include "Interaction/InteractionConfig.h"
#include "ItemActor.generated.h"
class USphereComponent;
class ABaseFoodActor;
class AChairSeat;
class AShootCharacter;
class APlateSystem;
class UTexture2D;
class UWidgetComponent;

UENUM(BlueprintType)
enum class EItemState : uint8
{
	EIS_Idle UMETA(DisplayName = "Idle"),
	EIS_Hovering UMETA(DisplayName = "Hovering"),
	EIS_Equipped UMETA(DisplayName = "Equipped"),
	EIS_Cooking UMETA(DisplayName = "Cooking"),
	EIS_Pickup UMETA(DisplayName = "Pickup"), // 用来标志是不是碟子，用来装菜
};
DECLARE_DYNAMIC_MULTICAST_DELEGATE(FSpawnActorEvent);
DECLARE_DYNAMIC_MULTICAST_DELEGATE(FRemoveActorEvent); //移除碟子的时候触发事件（由 ADish 使用）
DECLARE_DYNAMIC_MULTICAST_DELEGATE(FChangeAttachActorEvent);

/** 食材解锁状态变化广播（true=已解锁可交互；false=已锁定） */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FIngredientUnlockStateChanged, bool, bUnlocked);

/** 熟度子阶段变化广播（按每个果实独立）：参数：阶段索引(0=未成熟/1=成熟/2=熟过头), 阶段名 */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FRipenessStageChanged, int32, StageIndex, FName, StageName);

class UBaseGameInstance;

UCLASS()
class SHOOT_API AItemActor : public AActor, public IHoveringInterface
{
	GENERATED_BODY()
	
public:	
	// Sets default values for this actor's properties
	AItemActor();

	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	virtual void AttachMeshToSocket(USceneComponent* InParent, const FName& InSocketName);

	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	virtual void DeAttachMeshToSocket();

	/** 挂到插槽时保持挂接前的世界缩放：角色骨架手部插槽通常带 2.25 骨骼缩放，
	 *  SnapToTarget 会把食物一起放大（煎蛋变巨无霸）。武器等需要跟随插槽缩放的物品可关掉。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	bool bPreserveWorldScaleOnAttach = true;

	/**
	 * 开启物理下落（投掷 / 松手掉落）。
	 *
	 * ItemMesh 平时是 NoCollision + 对所有通道 Ignore（避免食物挡住玩家），
	 * 但这样一旦 SetSimulatePhysics(true) 就完全没有阻挡，会直接穿过地板掉出世界。
	 * 所以物理必须和碰撞成对打开：只对世界几何（WorldStatic / WorldDynamic）Block，
	 * Pawn / Camera / Visibility 仍然 Ignore —— 落地不穿地，但不会把玩家挡在过道里。
	 * 同时打开 CCD，防止快速下落时隧穿薄地板。
	 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	void EnablePhysicsDrop();

	/** 兜底：如果蓝图把 ItemMesh 设成模拟物理（BP_Plate / BP_Beef 等确实勾了），
	 *  就必须补上"能落地"的碰撞，否则有重力无阻挡 → 生成即穿地板。 */
	void EnsurePhysicsIsSafe();

	UFUNCTION(BlueprintImplementableEvent, Category = "Shoot|Item")
	void OnSphereOverlapEvent();

	UFUNCTION(BlueprintImplementableEvent, Category = "Shoot|Item")
	void OnSphereEndOverlapEvent();		

protected:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;
	bool CanInteract();
	
private:
	bool bIsHovering = false;
	EItemState ItemState = EItemState::EIS_Idle;
	bool bSetOutline = false;

	/** 当前是否是角色的"唯一交互目标"（描边的唯一依据） */
	bool bInteractionHighlight = false;
	bool bManualHighlightRequested = false;
	TSet<TWeakObjectPtr<AActor>> InteractionHighlightRequesters;
	void RefreshInteractionHighlightRequests();

	/** 是否在树上结果中（由植物生成果实时开启，采摘/离树时关闭），控制熟度计时是否推进 */
	bool bTrackRipening = false;

	/** 插槽挂接前的世界缩放，摘下时还原，避免手部骨骼缩放残留到落地物品上 */
	FVector AttachWorldScaleBefore = FVector::OneVector;
	bool bAttachScaleCompensated = false;

	/** 当前熟度子阶段：0=未成熟, 1=成熟, 2=熟过头（仅用于广播去重，避免每帧重复） */
	int32 CurrentRipenessStage = 0;
public:	
	// Called every frame
	virtual void Tick(float DeltaTime) override;

	/** 编辑器里改 InteractionRadius / InteractionCenterHeight 时立即把值写进组件，
	 *  这样在关卡视口中摆放时看到的就是运行时真正生效的判定球，而不是蓝图残留的旧半径 */
	virtual void OnConstruction(const FTransform& Transform) override;

	/** 把 InteractionRadius / InteractionCenterHeight（× Shoot.InteractScale 倍率）应用到 Sphere 与 CollectSphere。
	 *  OnConstruction（编辑器）、BeginPlay（运行时）、运行时改倍率都会调用，必须幂等 */
	UFUNCTION()
	void ApplyInteractionScale();
	
	UFUNCTION()
	virtual void OnSphereOverlap( UPrimitiveComponent* OverlappedComponent, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 OtherBodyIndex, bool bFromSweep, const FHitResult & SweepResult) override;
	UFUNCTION()
	virtual void OnSphereEndOverlap( UPrimitiveComponent* OverlappedComponent, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 OtherBodyIndex) override;

	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	FORCEINLINE EItemState GetItemState() const { return ItemState; }
	
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	FORCEINLINE void SetItemState(EItemState State){ItemState = State;}

	/** 交互高亮（描边）：由角色按"当前唯一交互目标"统一点亮/熄灭。
	 *  旧实现是每个物体在 Overlap 时按自己的 Hovering 状态点亮，站在一堆食材中间会亮成一片；
	 *  每位本地玩家只申请当前目标；共享 CustomDepth 呈现各玩家目标的并集。
	 *  植物另由 APlant 按可采摘等状态管理。 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	virtual void SetInteractionHighlight(bool bEnable);

	/** 每个本地玩家独立申请描边；一位玩家移开不会清掉另一位的目标。 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	void SetInteractionHighlightForPlayer(AActor* Player, bool bEnable);

	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item")
	FORCEINLINE bool IsInteractionHighlighted() const { return bInteractionHighlight; }

	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	FORCEINLINE int32 GetMenuFoodID() const { return MenuFoodID; }

	/** 读取物品 ID（取自数据表行名 RowName；行名不是数字时退回行内 ItemID 字段）；未配置或取不到返回 -1。
	 *  研究炉按此 ID 匹配研究配方。 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item")
	int32 GetItemID() const;

	/** 读取物品图标（取自 ItemInfoRow / DT_ItemInfo 的 Icon）；未配置返回 null */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item")
	UTexture2D* GetItemIcon() const;

	UFUNCTION(BlueprintCallable, Category = "Shoot|Item")
	FORCEINLINE void SetMenuFoodID(int32 InID) { MenuFoodID = InID; }

	void ReserveServingPlate(APlateSystem& PlateSystem);
	bool ReturnServingPlate();

	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Shoot|Item")
	UStaticMeshComponent* ItemMesh;

	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Shoot|Item")
	USphereComponent* Sphere;

	// ============ 交互判定尺度（统一标准，见 InteractionConfig.h） ============
	/** 拾取判定球半径。C++ 在 BeginPlay 强制应用，会覆盖蓝图组件上残留的旧值，
	 *  保证所有食材的拾取手感一致；个别物品要特殊处理就改这里，不要改组件上的半径 */
	UPROPERTY(EditDefaultsOnly, Category = "Shoot|Interaction")
	float InteractionRadius = InteractionDistance::Item;

	/** 判定球心相对 Actor 原点的高度：抬到物体中部，
	 *  否则贴地的球只在脚踝高度有判定，表现为“站旁边也按不出反应” */
	UPROPERTY(EditDefaultsOnly, Category = "Shoot|Interaction")
	float InteractionCenterHeight = InteractionDistance::CenterHeight;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	USceneComponent* HandIK_LPoint;
	
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	USceneComponent* HandIK_RPoint;
	
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	TObjectPtr<class UMaterialInterface> OverlayMaterial;

	/** 物品信息数据表行引用（DataTable: ItemInfo） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item", meta = (RowType = "ItemActorInfo"))
	FDataTableRowHandle ItemInfoRow;
	
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Force")
	float ImpuseIntensity = 800.0f;
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Force")
	float ImpuseUpDirectionIntensity = 0.35f;
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Force")
	float ImpuseForwadDirectionIntensity = 1.0f;
	
	UPROPERTY(EditAnywhere,BlueprintReadWrite, Category = "Shoot|Item")
	TArray<int> FoodIdArray;

	UPROPERTY(EditAnywhere,BlueprintReadWrite, Category = "Shoot|Item")
	TArray<ABaseFoodActor*> FoodArray;

	UPROPERTY(EditAnywhere,BlueprintReadWrite, Category = "Shoot|Item")
	TObjectPtr<AActor> PreAttachActor;

	/** 该成品对应的菜单菜品 ID（由烹饪机生成成品时写入），供上菜台校验是否在菜单中（-1 表示未设置） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	int32 MenuFoodID = -1;

	/** 是否可被玩家拾取：false 时禁用本 ItemActor 的拾取（Pickable）逻辑，仅作为场景普通物件
	 *  （例如挂在树上、由植物统一采摘入背包的果实）。默认 true。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	bool bPickable = true;

	/** 能否装入外出背包（AOutdoorBasket）：false 表示这种食材只能手持携带、必须去野外现摘
	 *  （如生菜），背着篮子采摘会被拒绝并提示。默认 true。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item")
	bool bCanStoreInBasket = true;

	/** 物品显示名（优先数据表 DisplayName，其次 ItemDes，最后 Actor 名），用于文字反馈 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item")
	FString GetItemDisplayName() const;

	// ========== 成品腐烂（未被玩家持有一段时间后自动销毁） ==========
	/** 是否启用腐烂：被启用后，若成品未被玩家拾取（不在手上），累计超过 DecayTime 则自动销毁。
	 *  玩家"拾取起来"时计时【暂停】（保留已累计时长，不清零）；"放下"后从原值【继续累计】。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Decay")
	bool bEnableDecay = false;

	/** 是否输出调试信息（屏幕消息） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Decay")
	bool bShowDebugInfo = false;

	/** 腐烂时限（秒）：未被玩家持有超过该时长即自动销毁 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Decay", meta = (EditCondition = "bEnableDecay", ClampMin = "0.5"))
	float DecayTime = 30.f;

	/** 临近腐烂提前量（秒）：距腐烂还剩该时长时广播 OnDecayWarning，供蓝图变色/动画（<=0 表示不预警） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Decay", meta = (EditCondition = "bEnableDecay", ClampMin = "0"))
	float DecayWarnLeadTime = 8.f;

	/** 运行时累计的"未被持有"时长（只读；在手上的那一刻会被清零） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Item|Decay")
	float DecayTimer = 0.f;

	/** 腐烂销毁时广播（蓝图可做淡出/特效后再 Destroy 也可监听做反馈） */
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Item|Decay")
	FSpawnActorEvent OnDecayed;

	/** 临近腐烂时广播一次（进入警告窗口且尚未通知过），供蓝图做变色/循环动画，如：闪红、冒泡提示。
	 *  玩家捡起（计时暂停）会复位该状态，放下后若再次临近会重新广播。 */
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Item|Decay")
	FSpawnActorEvent OnDecayWarning;

	/** 由烹饪机在生成成品时调用，开启腐烂并设置时限 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item|Decay")
	void EnableDecay(float InDecayTime);

	/** 当前腐烂进度 0~1（DecayTimer / DecayTime），蓝图可每帧读取做平滑变色 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item|Decay")
	float GetDecayProgress() const { return DecayTime > 0.f ? FMath::Clamp(DecayTimer / DecayTime, 0.f, 1.f) : 0.f; }

	/** 是否已经广播过临近警告（避免每帧重复广播）；普通成员，不暴露给蓝图 */
	bool bDecayWarned = false;

	UPROPERTY(EditAnywhere,BlueprintReadWrite, Category = "Shoot|Item")
	TSubclassOf<class AItemActor> SpawnItemActorClass;

	UFUNCTION(BlueprintCallable, Category = "Shoot|Gameplay",
		  meta = (DisplayName = "设置后处理描边"))
	static void SetActorsOutline(AActor* actor,bool bEnable);
	
	void OnClear();

	bool NeedOutLineEffect();
	
	UFUNCTION(BlueprintImplementableEvent, Category = "Shoot|Effect Events")
    void OnGiveEffectEvent();

	UPROPERTY(BlueprintAssignable, Category = "Shoot|Events")
	FChangeAttachActorEvent OnChangeAttachActorEvent;

	// ========== 食材解锁（关卡达成目标后解锁场景上预先放置的食材，如玉米田里的玉米） ==========
	/** 食材解锁 ID：>=0 表示需要对应 ID 解锁后才能交互（如玉米田里的玉米）；<0 表示无需解锁，默认可交互。
	 *  解锁由 UBaseGameInstance 统一管理（关卡达成目标后 UnlockIngredients）。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Unlock")
	int32 IngredientUnlockID = -1;

	/** 运行时是否已解锁（<0 的 ID 永远为 true） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Item|Unlock")
	bool bIngredientUnlocked = true;

	/** 解锁状态变化广播（true=已解锁可交互；false=已锁定）。蓝图做锁定/解锁视觉，如变灰→变亮、显示“已解锁”飘字 */
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Item|Unlock")
	FIngredientUnlockStateChanged OnIngredientUnlockStateChanged;

	/** 设置解锁状态并广播（供内部与 GameInstance 解锁事件调用） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item|Unlock")
	void SetIngredientUnlocked(bool bUnlocked);

	/** 监听 GameInstance 的食材解锁广播 */
	UFUNCTION()
	void HandleIngredientsUnlocked(const TArray<int32>& UnlockedIDs);

	// ========== 品质（食材采摘阶段 / 成品由食材最差品质决定） ==========
	/** 品质：普通 / 佳品 / 次品。食材在采摘瞬间由植物按熟度写入；成品由烹饪机取最差食材品质写入。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Quality")
	EIngredientQuality IngredientQuality = EIngredientQuality::Normal;

	/** 读取品质（供上菜结算额外奖励、UI 显示） */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item|Quality")
	EIngredientQuality GetIngredientQuality() const { return IngredientQuality; }

	/** 设置品质 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item|Quality")
	void SetIngredientQuality(EIngredientQuality InQuality) { IngredientQuality = InQuality; }

	void ShowPremiumDishFeedback();
	void ClearPremiumDishFeedback();

	// ========== 熟度（素材结果后的“成熟 / 熟过头”子阶段，按每个果实独立计时） ==========
	/** 是否启用熟度：由植物在生成果实时按 PlantInfo 写入 */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Item|Ripeness")
	bool bEnableRipeness = false;

	/** 成熟时间点（秒，距结果起）：此窗口内采摘 = 佳品（供 UI 进度条画刻度） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Item|Ripeness")
	float RipeTime = 0.f;

	/** 熟过头时间点（秒，距结果起）：此窗口后采摘 = 次品（供 UI 进度条画刻度） */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Item|Ripeness")
	float OverripeTime = 0.f;

	/** 熟度计时（秒）：仅在“在树上结果中”（bTrackRipening=true）时推进 */
	UPROPERTY(BlueprintReadOnly, Category = "Shoot|Item|Ripeness")
	float RipenessTimer = 0.f;

	/** 由植物在生成果实时写入熟度配置并启动计时（从“未成熟”开始累计） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item|Ripeness")
	void ConfigureAndStartRipening(bool bEnable, float InRipeTime, float InOverripeTime);

	/** 停止熟度计时（采摘离树 / 销毁前调用），此后品质已固定不再变化 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item|Ripeness")
	void StopRipening();

	/** 当前熟度子阶段名（未成熟 / 成熟 / 熟过头），用于 UI 提示该果实的阶段 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item|Ripeness")
	FName GetRipenessStageName() const;

	/** 熟度进度 0..1（距“熟过头”的进度），供 UI 进度条显示 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item|Ripeness")
	float GetRipenessProgress() const;

	/** 当前采摘品质：成熟=佳品，熟过头=次品，未成熟/未启用=普通 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|Item|Ripeness")
	EIngredientQuality GetCurrentQuality() const;

	/** 熟度子阶段变化广播（供 UI 绑定单个果实做文字/进度刷新） */
	UPROPERTY(BlueprintAssignable, Category = "Shoot|Item|Ripeness")
	FRipenessStageChanged OnRipenessChanged;

	// ========== 空碟 / 脏碟（方案B 用餐闭环 + 洗碗机回收） ==========
	/** 是否为“桌上空碟”：客人吃完后留下的，占据座位直到玩家按 E 收走 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Plate")
	bool bIsEmptyPlate = false;

	/** 是否为“脏碟”：玩家从桌上收走、拿在手上待交还洗碗机的碟子 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|Item|Plate")
	bool bIsDirtyPlate = false;

