	UPROPERTY(BlueprintAssignable, Category = "Shoot|Item|Decay")
	FSpawnActorEvent OnDecayWarning;

	/** 由烹饪机在生成成品时调用，开启腐烂并设置时限 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|Item|Decay")
	void EnableDecay(float InDecayTime);

