// Fill out your copyright notice in the Description page of Project Settings.

#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "NPC/GuestCharacter.h"
#include "GuestManager.generated.h"

class AGuestCharacter;
class UTimeSystem;
class UUserWidget;
class UTexture2D;
class USoundBase;
class UBusinessSignWidget;

/** 打烊收尾完成广播：已点菜的客人都处理完（上完菜 / 等待超时离场）后才触发，表示"真正打烊、可以结束这一天" */
DECLARE_DYNAMIC_MULTICAST_DELEGATE(FOnClosingFinishedSignature);

/** 备料窗口变化：bOpen=true 表示波峰刚结束、进入可离场窗口；Seconds 为本次窗口时长（秒）。
 *  供 HUD 倒计时、野外事件与限时野味订单监听；窗口关闭时 bOpen=false、Seconds=0。 */
DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FOnPrepWindowChangedSignature, bool, bOpen, float, Seconds);

/**
 * 客人统一管理器：负责按配置周期性生成 / 销毁 GuestCharacter，
 * 维护在场客人列表，并约束最大同时在场数量（避免抢占过多座位）。
 * 在关卡中放置一个此 Actor，并指定 GuestClass 为你的客人蓝图。
 */
UCLASS()
class SHOOT_API AGuestManager : public AActor
{
	GENERATED_BODY()

public:
	AGuestManager();

	/** 要生成的客人蓝图类（需继承自 AGuestCharacter） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	TSubclassOf<AGuestCharacter> GuestClass;

	/** 客人生成点；若为空则使用管理器自身位置 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	FVector SpawnLocation = FVector::ZeroVector;

	/** 客人离场目标点（传给每个生成出的客人） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	FVector LeaveLocation = FVector::ZeroVector;

	/** 最大同时在场客人数量（基础值；实际容量还会叠加声誉与“新餐桌”道具加成） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	int32 MaxGuests = 6;

	/** 容量随声誉提升：每多少声誉 +1 容量（数值越小，声誉对客人数量的拉动越明显） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	int32 GuestsPerReputation = 10;

	/** 每持有 1 个“新餐桌”(道具ID=1001) 额外增加的容量 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	int32 ExtraGuestsPerTable = 2;

	/** 容量绝对上限（防止数值爆炸） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	int32 MaxGuestsHardCap = 30;

	/** 自动生成间隔（秒），<=0 表示不自动生成 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	float SpawnInterval = 16.0f;

	/** 开门后店内无客时，第一位客人的等待时间；后续仍使用正常来客间隔。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.1", Units = "s"))
	float FirstGuestArrivalDelay = 0.5f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.1"))
	float FirstRushDelay = 12.0f;

	/** 两次波峰开始的间隔（秒），运行时至少比波峰持续时间多 0.1 秒 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.2"))
	float RushInterval = 70.0f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.1"))
	float RushDuration = 22.0f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.1"))
	float RushSpawnInterval = 3.5f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.1"))
	float SpawnRetryDelay = 3.0f;

	// ========== 开业前期节奏（逐个来客，避免开场长时间空窗后一下涌入） ==========
	/** 前期来客节奏表：每个元素表示一次来客事件生成几位客人，按顺序消费。
	 *  例如 {1,1,1,2,1,2}：先来 1 位，再来 1 位……表走完后才进入常规波峰循环。清空 = 不开前期节奏。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|EarlyGame")
	TArray<int32> EarlyArrivalPattern;

	/** 前期节奏中相邻两次来客事件的间隔（秒）；表走完后恢复 SpawnInterval / 波峰节奏 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|EarlyGame", meta = (ClampMin = "1.0", Units = "s"))
	float EarlyArrivalInterval = 12.f;

	// ========== 未点单积压闸门（玩家一直不接单时停止进客） ==========
	/** 未点单客人积压上限：在场（含排队）尚未被玩家接单的客人达到该数量时暂停生成新客，
	 *  玩家接单、积压降到上限以下后自动恢复。0 = 不限制（旧行为）。
	 *  默认 3：前期来客 1,1,1 三位都没点单，就不会再进第 4 位。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|OrderGate", meta = (ClampMin = "0"))
	int32 MaxUnorderedGuestsBeforePause = 3;

	/** 当前未点单客人数（在场 + 排队中，尚未进入等菜/进食等已接单状态）；供 UI / 调试 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|GuestManager|Pacing|OrderGate")
	int32 GetUnorderedGuestCount() const;

	// ========== 离场后的来客间隔（避免前一位刚走、下一位立刻冒出来） ==========
	/** 任意客人离场（吃完离开 / 生气离场 / 超时离开）后，至少间隔这么多秒才会生成下一位客人。
	 *  0 = 关闭该间隔（保持旧行为）。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing", meta = (ClampMin = "0.0", Units = "s"))
	float SpawnDelayAfterGuestLeave = 5.f;

	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Shoot|GuestManager|Pacing")
	bool bInCustomerRush = false;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|UI")
	TSubclassOf<UUserWidget> RushBannerClass;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|UI")
	FText RushBannerText;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|UI")
	FText RushBannerDescription;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|UI")
	TObjectPtr<UTexture2D> RushBannerIcon = nullptr;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Pacing|UI", meta = (ClampMin = "0.1", Units = "s"))
	float RushBannerSeconds = 3.0f;

	// ========== 备料窗口（波峰结束后的可离场时段，配合第 16 节野外玩法） ==========
	/** 是否启用备料窗口：关闭则波峰结束后不做任何放宽，行为与旧版完全一致 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow")
	bool bEnablePrepWindow = true;

	/** 备料窗口时长（秒）。实际时长还会被「距下一次波峰的剩余时间 -2 秒」截断，保证能赶回来 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow", meta = (ClampMin = "1.0", Units = "s"))
	float PrepWindowSeconds = 30.f;

	/** 窗口内的来客间隔（秒）：只在比 SpawnInterval 更慢时生效，只放宽不收紧 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow", meta = (ClampMin = "0.1", Units = "s"))
	float PrepWindowSpawnInterval = 25.f;

	/** 窗口内给在场订单追加的超时宽限（秒）：叠加到 UOrderHandle 的 LateServeGraceSeconds 之上，窗口结束还原 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow", meta = (ClampMin = "0.0", Units = "s"))
	float PrepWindowOrderGraceSeconds = 8.f;

	/** 当前是否处于备料窗口（运行时只读） */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Shoot|GuestManager|PrepWindow")
	bool bInPrepWindow = false;

	/** 备料窗口变化广播（HUD / 野外事件 / 限时野味订单监听） */
	UPROPERTY(BlueprintAssignable, Category = "Shoot|GuestManager|PrepWindow")
	FOnPrepWindowChangedSignature OnPrepWindowChanged;

	/** 备料窗口提示横幅文本（复用 RushBannerClass 的 WBP_EventBanner） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow|UI")
	FText PrepWindowText;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow|UI")
	FText PrepWindowDescription;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow|UI")
	TObjectPtr<UTexture2D> PrepWindowIcon = nullptr;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|PrepWindow|UI", meta = (ClampMin = "0.1", Units = "s"))
	float PrepWindowBannerSeconds = 3.f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign", meta = (ClampMin = "0.1", Units = "s"))
	float BusinessSignSeconds = 3.f;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign")
	FText BusinessOpenText;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign")
	FText BusinessClosedText;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign")
	FText BusinessOpenDescription;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign")
	FText BusinessClosedDescription;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign")
	TObjectPtr<USoundBase> BusinessOpenSound;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign")
	TObjectPtr<USoundBase> BusinessClosedSound;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|BusinessSign", meta = (ClampMin = "0.0", ClampMax = "1.0"))
	float BusinessSignSoundVolume = 0.7f;

	/** 是否自动开始生成 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	bool bAutoSpawn = true;

	/** 是否打印生成诊断信息（失败原因、生成坐标、场景座位数等） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager")
	bool bShowDebugInfo = true;

	/** 接单方式：自动接单 / 需要玩家接单（会统一覆盖下发给每个生成出的客人）。
	 *  默认“需要玩家接单”：客人坐下后等待玩家靠近按 E 接单，接单后才真正出现订单。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Order")
	EGuestOrderAcceptMode OrderAcceptMode = EGuestOrderAcceptMode::NeedPlayerAccept;

	/** 生成特殊客人的概率（0~1）。特殊客人完成订单会获得额外声誉（见 AGuestCharacter::SpecialReputationBonus） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager", meta = (ClampMin = "0.0", ClampMax = "1.0"))
	float SpecialGuestChance = 0.2f;

	/** 当前在场客人列表 */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Shoot|GuestManager")
	TArray<TObjectPtr<AGuestCharacter>> ActiveGuests;

	/** 正在排队等待的客人（找不到座位时在此等候，队首最先入座） */
	UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category = "Shoot|GuestManager")
	TArray<TObjectPtr<AGuestCharacter>> WaitingQueue;

	/** 排队等候时客人的徘徊范围半径（cm）：客人会在管理器附近该范围内随机游走 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Queue", meta = (ClampMin = "50.0"))
	float QueueWanderRadius = 250.0f;

	/** 徘徊时每次驻足（停）的最短时长（秒） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Queue", meta = (ClampMin = "0.0"))
	float QueueWanderPauseMin = 0.5f;

	/** 徘徊时每次驻足（停）的最长时长（秒） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Queue", meta = (ClampMin = "0.0"))
	float QueueWanderPauseMax = 2.0f;

	/** 排队等待超时后扣除的声誉（赛季版本默认 5；关卡蓝图实例若覆盖了旧值需手动同步） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Queue")
	int32 ReputationPenaltyOnWaitTimeout = 5;

	/** 是否绘制等候区可视化（蓝色圆环=徘徊范围，绿球=每位等待客人当前位置） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Debug")
	bool bDrawQueueDebug = true;

	/** 是否绘制生成点/离场点（绿=Spawn，红=Leave，黄=Leave 为默认零向量警告），方便检查配置 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Debug")
	bool bDrawSpawnLeaveDebug = true;

	/** 座位占用情况自动打印间隔（秒）；<=0 表示不自动打印，可随时调用 PrintSeatStatus 手动打印 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Debug", meta = (ClampMin = "0.0"))
	float SeatStatusLogInterval = 0.f;

	// ========== 打烊收尾（延迟真正打烊） ==========
	/** 打烊时是否保留"已点菜"的客人：等玩家把菜上完，或客人等待超时离场，才真正打烊结束这一天。
	 *  关闭则退回旧行为（打烊立刻清走所有客人）。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Closing")
	bool bKeepOrderedGuestsOnClose = true;

	/** 打烊收尾的最长等待时间（秒）：兜底防止客卡住导致永远打不了烊。<=0 表示不设上限。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Closing", meta = (ClampMin = "0.0"))
	float ClosingMaxWaitTime = 120.f;

	/** 打烊前停止进客：距打烊不足 StopAdmissionHoursBeforeClose 个经营小时时不再生成新客人，
	 *  避免新客点了单却做不完，打烊被计为失败。已进场的客人不受影响。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Closing")
	bool bStopAdmissionBeforeClose = true;

	/** 距打烊提前多少“经营小时”停止进新客（默认 2 小时；0 = 到打烊点才停） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Closing", meta = (ClampMin = "0.0"))
	float StopAdmissionHoursBeforeClose = 2.0f;

	/** 当前是否已停止进新客（营业中且距打烊不足配置时长；运行时只读） */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|GuestManager|Closing")
	bool IsAdmissionStopped() const;

	/** 本地双人分屏压力缩放：每多 1 名玩家，容量与来客频率乘以 (1 + CoopPressurePerExtraPlayer)。
	 *  只放大经营压力，不动备料窗口时长（外勤位必须赶得回来）。 */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Coop", meta = (ClampMin = "0.0"))
	float CoopPressurePerExtraPlayer = 0.7f;

	/** 当前联机压力倍率（1 名玩家 = 1.0；运行时只读） */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|GuestManager|Coop")
	float GetCoopPressureScale() const;

	/** 调试球半径（cm） */
	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Shoot|GuestManager|Debug", meta = (ClampMin = "1.0"))
	float QueueDebugSphereRadius = 30.0f;

	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

	virtual void Tick(float DeltaSeconds) override;

	/** 立即生成一个客人（受 MaxGuests 限制）。返回生成的实例，或 nullptr */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager")
	AGuestCharacter* SpawnGuest();

	/** 一次性连续生成最多 Count 个客人（仍受 MaxGuests 限制，满了即停）。供招揽台调用 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager")
	void SpawnGuestsBurst(int32 Count);

	/** 实际可容纳上限 = 基础 + 声誉加成 + 新餐桌道具加成（运行时动态计算） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager")
	int32 GetEffectiveMaxGuests() const;

	/** 由客人销毁前调用，把自己从在场列表移除 */
	void UnregisterGuest(AGuestCharacter* Guest);

	/** 清空并销毁所有在场客人 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager")
	void ClearAllGuests();

	/** 暂停自动生成（打烊/过渡期间调用，避免清场后倒计时内又冒出新客人重新占座） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager")
	void PauseSpawning();

	/** 恢复自动生成（进入下一关后调用） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager")
	void ResumeSpawning();

	/** 手动开启备料窗口（关卡脚本 / 调试用）。Seconds<=0 时按 PrepWindowSeconds；重复调用会重置计时 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|PrepWindow")
	void OpenPrepWindow(float Seconds = 0.f);

	/** 手动关闭备料窗口（恢复来客节奏与订单宽限，并广播 bOpen=false） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|PrepWindow")
	void ClosePrepWindow();

	/** 当前生效的来客间隔：备料窗口内取更慢的那个值 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|GuestManager|PrepWindow")
	float GetEffectiveSpawnInterval() const;

	/** 客人入队：返回分配的排队序号，并把它摆到对应的队列位置（重复入队会移到队尾） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Queue")
	int32 EnqueueGuest(AGuestCharacter* Guest);

	/** 客人离队（入座/超时/离场时调用），并重新排布剩余客人 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Queue")
	void RemoveFromQueue(AGuestCharacter* Guest);

	/** 等候徘徊区的中心点（即管理器位置），供徘徊与调试绘制使用 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Queue")
	FVector GetQueueWanderCenter() const;

	/** 有空位时调用：把队首等待客人提升去占座 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Queue")
	void OnSeatFreed();

	// —— 打烊收尾（延迟真正打烊） ——
	/** 是否处于"打烊收尾中"：已打烊但还有已点菜客人未处理完 */
	UFUNCTION(BlueprintCallable, BlueprintPure, Category = "Shoot|GuestManager|Closing")
	bool IsClosingPending() const { return bClosingPending; }

	/** 该客人是否需要在打烊时保留（已点菜 / 正在进食：等上菜或超时后才算处理完） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Closing")
	bool IsGuestNeedKeepOnClose(const AGuestCharacter* Guest) const;

	/** 统计当前仍需保留（未处理完）的客人数 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Closing")
	int32 GetPendingClosingGuestCount() const;

	/** 真正完成打烊：清掉剩余客人并广播 OnClosingFinished（由收尾检测/兜底超时调用） */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Closing")
	void FinishClosing();

	/** 打印场景上所有座位的占用情况（占用/空闲及占用者），用于调试；蓝图/控制台可随时调用 */
	UFUNCTION(BlueprintCallable, Category = "Shoot|GuestManager|Debug")
	void PrintSeatStatus();

	/** 打烊收尾完成：已点菜的客人都处理完（上完菜 / 等待超时离场），可以真正结束这一天。
	 *  蓝图/关卡可监听此事件做结算、切下一天等。 */
	UPROPERTY(BlueprintAssignable, Category = "Shoot|GuestManager|Closing")
	FOnClosingFinishedSignature OnClosingFinished;

	/** 排队等待超时：移出队列并扣除声誉（由客人调用） */
	void HandleQueueTimeout(AGuestCharacter* Guest);

private:
	/** 营业状态变化：开营恢复自动生成，打烊停生成并清场 */
	UFUNCTION()
	void OnBusinessOpenChanged(bool bOpen);

	TWeakObjectPtr<UTimeSystem> BoundTimeSystem;
	UTimeSystem* BindBusiness();

	bool bSpawningPaused = true;
	bool bCustomerPacingStarted = false;
	double NextRushStartTime = 0.0;

	/** 最近一次客人离场的世界时间（秒）；用于 SpawnDelayAfterGuestLeave 的来客间隔 */
	double LastGuestLeaveWorldTime = -1.0;

	/** 前期来客节奏表已消费到的位置（每次开门营业从头开始） */
	int32 EarlyArrivalIndex = 0;

	/** 单次来客定时器；尚未找到 TimeSystem 时也用于重试绑定 */
	FTimerHandle AutoSpawnTimerHandle;
	FTimerHandle RushPhaseTimerHandle;

	/** 座位占用情况自动打印用的定时器 */
	FTimerHandle SeatStatusLogHandle;

	void TickSpawn();
	void ScheduleNextSpawn(float Delay);
	void AdvanceRushPhase();
	void ShowRushBanner();
	void HideRushBanner();
	void ShowBusinessSign(bool bOpen);
	void HideBusinessSign();

	/** 备料窗口：横幅提示、来客节奏、订单宽限 */
	void ShowPrepBanner(float Seconds);
	void HidePrepBanner();
	void ApplyPrepWindowGrace(float Seconds);
	FTimerHandle PrepWindowTimerHandle;
	FTimerHandle PrepBannerTimerHandle;

	UPROPERTY(Transient)
	TArray<TObjectPtr<UUserWidget>> PrepBanners;

	FTimerHandle BusinessSignTimerHandle;

	UPROPERTY(Transient)
	TArray<TObjectPtr<UBusinessSignWidget>> BusinessSigns;

	FTimerHandle RushBannerTimerHandle;

	UPROPERTY(Transient)
	TArray<TObjectPtr<UUserWidget>> RushBanners;

	/** 客人变动后刷新剩余等待客人的排队序号（不再摆放位置，位置由徘徊决定） */
	void RefreshQueueSlots();

	/** 每帧绘制等候徘徊范围与各等待客人位置（仅在 bDrawQueueDebug 时生效） */
	void DrawQueueDebug();

	/** 绘制生成点/离场点（仅在 bDrawSpawnLeaveDebug 时生效） */
	void DrawSpawnLeaveDebug() const;

	/** 打烊时清走"不需要保留"的客人（保留已点菜的），用于延迟打烊 */
	void ClearGuestsExcept(const TArray<AGuestCharacter*>& KeepList);

	/** 收尾检测：若已无待处理客人则真正完成打烊 */
	void CheckClosingFinished();

	/** 是否处于打烊收尾中（已打烊但仍有已点菜客人未处理完） */
	bool bClosingPending = false;

	/** 打烊收尾兜底超时定时器 */
	FTimerHandle ClosingTimeoutHandle;
};

